function feed(){const rows=[],errs=[],seen=new Set();P.filter(p=>!p.disabled).forEach(p=>variants(p).forEach(v=>{const r={id:v.id,title:p.name+' - '+v.c+' / '+v.s,description:p.desc||'',availability:p.stock>0?'in stock':'out of stock',condition:'new',price:p.price.toFixed(2)+' BDT',sale_price:p.sale?p.sale.toFixed(2)+' BDT':'',link:CFG.meta.domain+'/#product-'+p.id,image_link:CFG.meta.imageBase?CFG.meta.imageBase+v.id+'.jpg':'',brand:'JUPTEE',google_product_category:GPC[p.cat]||'Apparel & Accessories > Clothing > Shirts & Tops',product_type:'Apparel > '+CATS[p.cat],item_group_id:p.code,color:v.c,size:v.s,gender:'unisex',age_group:'adult',inventory:p.stock};['title','description','image_link','link'].forEach(k=>{if(!r[k])errs.push(v.id+': missing '+k)});if(seen.has(r.id))errs.push(v.id+': duplicate id');seen.add(r.id);rows.push(r)}));return{rows,errs}}
