function page(k){const g=PG[k];if(!g)return nf();let body='';
if(k=='size')body=`<p class="policy-intro">Use this Asian size chart to compare garment measurements with a T-shirt that fits you well. All measurements are in inches.</p><figure class="size-diagram"><svg viewBox="0 0 680 500" role="img" aria-labelledby="size-diagram-title size-diagram-desc"><title id="size-diagram-title">T-shirt measurement directions</title><desc id="size-diagram-desc">A front view of a T-shirt showing double-ended arrows for chest across the body, length from shoulder to hem, shoulder across the seams, and sleeve from the shoulder to the sleeve edge.</desc><defs><marker id="measure-arrow" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#52634d"/></marker></defs><rect x="1" y="1" width="678" height="498" rx="26" fill="#f3f1ec"/><path class="tee-shape" d="M254 91 194 112 112 158l38 82 66-33v207h248V207l66 33 38-82-82-46-60-21c-13 22-35 34-62 34s-49-12-62-34z"/><path class="neck-shape" d="M278 99c10 31 28 46 48 46s38-15 48-46"/><line class="measure-line" x1="234" y1="273" x2="446" y2="273"/><line class="guide-line" x1="234" y1="244" x2="234" y2="294"/><line class="guide-line" x1="446" y1="244" x2="446" y2="294"/><rect class="measure-label-bg" x="287" y="245" width="106" height="34" rx="17"/><text class="measure-label" x="340" y="268" text-anchor="middle">CHEST</text><line class="measure-line" x1="482" y1="104" x2="482" y2="411"/><line class="guide-line" x1="449" y1="104" x2="496" y2="104"/><line class="guide-line" x1="449" y1="411" x2="496" y2="411"/><rect class="measure-label-bg" x="500" y="233" width="104" height="34" rx="17"/><text class="measure-label" x="552" y="256" text-anchor="middle">LENGTH</text><line class="measure-line" x1="259" y1="102" x2="409" y2="102"/><line class="guide-line" x1="259" y1="83" x2="259" y2="119"/><line class="guide-line" x1="409" y1="83" x2="409" y2="119"/><rect class="measure-label-bg" x="300" y="54" width="68" height="30" rx="15"/><text class="measure-label" x="334" y="74" text-anchor="middle">SHOULDER</text><line class="measure-line" x1="198" y1="122" x2="158" y2="211"/><circle class="measure-dot" cx="198" cy="122" r="4"/><circle class="measure-dot" cx="158" cy="211" r="4"/><rect class="measure-label-bg" x="45" y="103" width="82" height="32" rx="16"/><text class="measure-label" x="86" y="124" text-anchor="middle">SLEEVE</text></svg><figcaption>Measurement directions shown on a front-view tee. Match the size-chart values to a similar garment laid flat.</figcaption></figure><div class="table-wrap"><table class="policy-table"><thead><tr><th>Size</th><th>Chest</th><th>Length</th><th>Shoulder</th><th>Sleeve</th></tr></thead><tbody>${[['M','38','27','17','7.5'],['L','40','28','18','8'],['XL','42','29','19','8.5'],['XXL','44','30','20','9'],['3XL','46','31','21','9.5']].map(([s,chest,length,shoulder,sleeve])=>`<tr><td>${s}</td><td>${chest}"</td><td>${length}"</td><td>${shoulder}"</td><td>${sleeve}"</td></tr>`).join('')}</tbody></table></div><p class="note">For the best fit, compare these measurements with a garment that fits you comfortably.</p>`;
if(k=='shipping')body=`<div class="delivery-partner"><span class="partner-icon" aria-hidden="true">SF</span><div><span class="eyebrow">OUR DELIVERY PARTNER</span><h2>StatedFats Courier</h2><p>Select your district at checkout to see its fee included in the total.</p></div></div><div class="rate-cards">${[['Dhaka',CFG.delivery.dhaka,'01'],['Outside Dhaka',CFG.delivery.out,'02']].map(([area,fee,no])=>`<div class="rate-card"><span>${no}</span><b>${area}</b><strong>${tk(fee)}</strong></div>`).join('')}</div><div class="note">Dhaka district orders use the Dhaka fee. All other districts use the Outside Dhaka fee, calculated and confirmed by the order service.</div>`;
if(k=='returns')body=`<div class="return-steps">${[['01','Check your item','Inspect the item when it arrives.'],['02','Tell the delivery person','If you need a return or exchange, tell the delivery person immediately, before they leave.'],['03','Contact JUPTEE','Use the contact details below to coordinate availability and next steps.']].map(([n,title,copy])=>`<article class="return-step"><span>${n}</span><div><h3>${title}</h3><p>${copy}</p></div></article>`).join('')}</div><a class="btn" href="#p-contact">Contact JUPTEE <span aria-hidden="true">→</span></a><p class="fine-print">Exchange availability, next steps, and any applicable delivery charges should be confirmed directly with JUPTEE. This preview cannot create or track a return request.</p>`;
if(k=='contact')body=`<p class="policy-intro">Choose the best way to get in touch. For sizing or product questions, include the product name and size you are interested in.</p><div class="contact-list"><a class="contact-card" href="tel:+8801061103327"><span class="contact-icon" aria-hidden="true">☎</span><span class="eyebrow">CALL JUPTEE</span><b>+8801061103327</b><span class="contact-action">Call us <span aria-hidden="true">↗</span></span></a><a class="contact-card" href="mailto:hellojuptee@gmail.com"><span class="contact-icon" aria-hidden="true">✉</span><span class="eyebrow">GENERAL ENQUIRIES</span><b>hellojuptee@gmail.com</b><span class="contact-action">Send an email <span aria-hidden="true">↗</span></span></a><a class="contact-card" href="mailto:contact@jupbd.shop"><span class="contact-icon" aria-hidden="true">✉</span><span class="eyebrow">BUSINESS ENQUIRIES</span><b>contact@jupbd.shop</b><span class="contact-action">Send an email <span aria-hidden="true">↗</span></span></a></div>`;
if(k=='faq')body=`<div class="faq-tools"><label class="faq-search"><span aria-hidden="true">⌕</span><input type="search" placeholder="Search common questions..." aria-label="Search frequently asked questions" oninput="filterFAQs(this.value)"></label><div class="faq-actions"><span id="faq-count">6 answers</span><button type="button" class="text-btn" onclick="toggleFAQs(true)">Open all</button><button type="button" class="text-btn" onclick="toggleFAQs(false)">Close all</button></div></div><div class="faq-list">${[['How do I choose my size?','Use the Asian size guide to compare chest, length, shoulder, and sleeve measurements in inches. For the best fit, compare them with a similar garment that fits you well.'],['How much is delivery?','Delivery is ৳80 for Dhaka district and ৳130 for all other districts by default. Choose your district at checkout; the order service calculates the fee.'],['Can I return or exchange an item?','If you need a return or exchange, tell the delivery person immediately at delivery, before they leave. Contact JUPTEE to coordinate availability and next steps.'],['How do I contact JUPTEE?','Call +8801061103327, email hellojuptee@gmail.com, or email contact@jupbd.shop.'],['Can I place an order or pay online here?','When the secure order service is deployed and a verified product variant is in stock, checkout saves orders for cash on delivery. The current storefront still uses sample products and prices, so confirm availability with JUPTEE before ordering.'],['Are the products and prices final?','No. The products, prices, and stock displayed are sample preview data. Only the server catalogue determines whether an item can be ordered and its final price.']].map(([q,a])=>`<details class="faq-item"><summary>${q}<span class="faq-chevron" aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}<p class="faq-empty" hidden>No questions match that search. Try another word.</p></div>`;
if(k=='refund')body='<div class="policy-callout"><span class="callout-mark">i</span><div><b>Cash on delivery</b><p>Online payment is not collected on this site. For a return, exchange, or refund question, contact JUPTEE as soon as possible. Return or exchange requests should be raised with the delivery person at delivery, before they leave.</p></div></div><a class="btn alt" href="#p-contact">Contact JUPTEE</a>';
if(k=='privacy')body='<div class="policy-callout"><span class="callout-mark">i</span><div><b>Order information</b><p>The order service is not live until Cloudflare is configured with verified products and notification credentials. Once live, if you place an order, JUPTEE receives your name, phone number, optional email, division, district, police station/upazila, delivery address, delivery instructions, items, and order notes. The order is stored in Cloudflare D1 and shared with authorized JUPTEE administrators; email and WhatsApp notifications are handled by Resend and Meta WhatsApp Cloud API and sent to the business contacts configured by JUPTEE. Customer details may be shared with the delivery partner to fulfill an order. Your bag and wishlist are also saved in your browser on this device. Contact JUPTEE to ask about your information or its deletion.</p></div></div><a class="btn alt" href="#p-contact">Privacy questions? Contact us</a>';
if(k=='terms')body='<div class="policy-callout"><span class="callout-mark">i</span><div><b>Sample catalogue and order acceptance</b><p>Products, prices, and stock displayed during setup are sample content and may not be available. The order service checks the verified server catalogue for current prices and stock. Orders are for cash on delivery; no online payment is collected. JUPTEE will contact customers to confirm order details and delivery. Delivery fees are ৳80 for Dhaka district and ৳130 for all other districts by default. Return or exchange requests must be raised with the delivery person at delivery, before they leave.</p></div></div><a class="btn alt" href="#shop">Browse the collection</a>';
return `<div class="bc"><a href="#home">Home</a><span aria-hidden="true">/</span><a href="#p-faq">Customer care</a><span aria-hidden="true">/</span><span>${g[0]}</span></div><section class="page-hero"><span class="eyebrow">JUPTEE · CUSTOMER CARE</span><h1>${g[0]}</h1><p>${g[1]}</p><span class="hero-orbit" aria-hidden="true"></span></section><div class="policy-layout"><section class="policy-content">${body}</section><aside class="policy-aside"><span class="eyebrow">NEED A HAND?</span><h2>We're happy to help.</h2><p>Questions about your fit, order, or delivery? Reach out to our team.</p><a class="aside-link" href="#p-contact">Get in touch <span aria-hidden="true">→</span></a><div class="aside-divider"></div><span class="eyebrow">QUICK LINKS</span><a class="quick-link" href="#p-size">Size guide <span aria-hidden="true">↗</span></a><a class="quick-link" href="#p-shipping">Shipping policy <span aria-hidden="true">↗</span></a><a class="quick-link" href="#p-returns">Returns & exchange <span aria-hidden="true">↗</span></a><a class="quick-link" href="#p-faq">Frequently asked questions <span aria-hidden="true">↗</span></a></aside></div>`}
function filterFAQs(query){const q=query.trim().toLowerCase(),items=[...document.querySelectorAll('.faq-item')];let visible=0;items.forEach(item=>{const show=item.textContent.toLowerCase().includes(q);item.hidden=!show;if(show)visible++});$('#faq-count').textContent=visible+' '+(visible==1?'answer':'answers');document.querySelector('.faq-empty').hidden=visible>0}
function toggleFAQs(open){document.querySelectorAll('.faq-item:not([hidden])').forEach(item=>item.open=open)}
function animatePage(){if(revealObserver)revealObserver.disconnect();const items=app.querySelectorAll('.card,.cat,.why>div,.faq-item,.contact-card,.rate-card,.return-step,.policy-aside');if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(item=>item.classList.add('is-visible'));return}revealObserver=new IntersectionObserver((entries,observer)=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});items.forEach(item=>{item.classList.add('reveal-on-scroll');revealObserver.observe(item)})}
function nf(){return '<h1>Page not found</h1><a class="btn" href="#home">Back to home</a>'}
function route(keep){const h=(location.hash||'#home').slice(1),[a,b]=[h.split('-')[0],h.slice(h.indexOf('-')+1)];document.body.classList.toggle('home-page',h==='home');
if(window._lh!=location.hash){window._lh=location.hash;track('PageView',{})}app.innerHTML=h=='home'?home():a=='shop'&&h!='shop'?shop(b):h=='shop'?shop():h=='wishlist'?wishlistPage():a=='product'?prod(b):h=='cart'?cartv():h=='checkout'?checkout():h=='done'?done():h=='about'?about():h=='meta'?meta():a=='p'?page(b):nf();if(h==='checkout'){const selector=$('#checkout-locations');if(selector&&window.initializeLocationSelectors){selector.addEventListener('locationchange',updateCheckoutTotals);window.initializeLocationSelectors(selector);updateCheckoutTotals()}}animatePage();
document.querySelectorAll('#nav a').forEach(x=>x.classList.toggle('on',x.getAttribute('href')=='#'+h));
const titleProduct=P.find(p=>p.id==b);document.title=h=='home'?'JUPTEE – Premium T-Shirts & Hoodies in Bangladesh':a=='p'&&PG[b]?'JUPTEE – '+PG[b][0]:h=='shop'?'JUPTEE – Shop':h=='shop-new'?'JUPTEE – New arrivals':a=='shop'?'JUPTEE – '+(CATS[b]||'Shop'):a=='product'?'JUPTEE – '+(titleProduct?titleProduct.name:'Product'):h=='about'?'JUPTEE – Our story':h=='wishlist'?'JUPTEE – Wishlist':h=='cart'?'JUPTEE – Your bag':h=='checkout'?'JUPTEE – Checkout':h=='done'?'JUPTEE – Order preview':h=='meta'?'JUPTEE – Catalog setup':'JUPTEE – '+h.replace(/-/g,' ');if(!keep)scrollTo(0,0)}
addEventListener('hashchange',()=>route());save();route();
async function loadPublishedProducts(){
try{
const response=await fetch('/api/products',{headers:{Accept:'application/json'}});
if(!response.ok)throw new Error(`Catalog request failed (${response.status}).`);
const result=await response.json();
if(!Array.isArray(result.products))throw new Error('The published product catalog response is invalid.');
const products=result.products.map(product=>({...product,images:Array.isArray(product.images)?product.images.map(siteAssetUrl):product.images,variants:product.variants.map(variant=>({id:variant.id,c:variant.color,s:variant.size,stock:variant.stock,unitPrice:variant.unitPrice}))}));
if(!products.length){console.warn('The published catalog is empty; keeping the sample storefront visible.');return}
const previous=P;
const resolveProduct=id=>{const old=previous.find(product=>product.id==id);return products.find(product=>product.id===(old?.code||id))};
cart=cart.map(item=>{const product=resolveProduct(item.id);if(!product)return null;const variant=variants(product).find(value=>value.c===item.c&&value.s===item.s);if(!variant||variant.stock<1)return null;return{...item,id:product.id,q:Math.min(item.q,variant.stock)}}).filter(Boolean);
wish=[...new Set(wish.map(id=>resolveProduct(id)?.id).filter(Boolean))];
P=products;liveCatalogLoaded=true;$('#store-status').textContent='JUPTEE · SHOP THE LATEST COLLECTION';$('#footer-store-status').textContent='Published collection · verified products and stock';save();route(1)
}catch(error){console.warn('The published catalog could not be loaded; showing the setup preview instead.',error)}
}
loadPublishedProducts();
async function loadStoreDeliverySettings(){try{const response=await fetch('/api/chat-settings',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Store settings request failed (${response.status}).`);const result=await response.json();if(!result.deliveryFees||!['dhaka','subcity','out'].every(key=>Number.isSafeInteger(result.deliveryFees[key])&&result.deliveryFees[key]>=0))throw new Error('Store delivery settings are invalid.');CFG.delivery=result.deliveryFees;if(location.hash==='#cart')route(1);else if(location.hash==='#checkout'){if($('#checkout-dhaka-fee'))$('#checkout-dhaka-fee').textContent=tk(CFG.delivery.dhaka);if($('#checkout-outside-fee'))$('#checkout-outside-fee').textContent=tk(CFG.delivery.out);updateCheckoutTotals()}}catch(error){console.warn('Configured store delivery fees could not be loaded; showing defaults.',error)}}
loadStoreDeliverySettings();
tm=setInterval(()=>{if((location.hash||'#home')=='#home'&&!matchMedia('(prefers-reduced-motion:reduce)').matches){slide=(slide+1)%slides.length;route(1)}},6000);